using System;
using System.Linq;
using Newtonsoft.Json.Linq;
namespace PortraitStudio.StaticV1 {
internal static class StaticWire {
internal static void Validate(JObject m) {
Check.That(m["protocol"]?.Value<string>() == Catalog.Format && m["contract"]?.Value<string>() == Catalog.Contract && m["renderMode"]?.Value<string>() == "static", "Invalid contract");
string[] required, allowed;
switch ((string)m["op"]) {
case "discover": required=new[] { "protocol", "contract", "renderMode", "op" }; allowed=new[] { "protocol", "contract", "renderMode", "op" }; break;
case "acquire": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targets" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targets" }; break;
case "select": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "choiceId", "mode", "setDefault" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "choiceId", "mode", "setDefault", "layout", "resource" }; break;
case "forget-choice": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "choiceIds" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "choiceIds" }; break;
case "plan": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch" }; break;
case "prepare": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId", "grant" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId", "grant" }; break;
case "commit": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; break;
case "rollback": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; break;
case "finish": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; break;
case "cancel": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "targetId", "displayId", "visitId", "choiceId", "transactionId", "surfaceId", "encounterId", "groupId", "presenterProviderId", "presentationRole", "displayEpoch", "planId", "reservationId" }; break;
case "trim": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "warmLimitBytes" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq", "warmLimitBytes" }; break;
case "heartbeat": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq" }; break;
case "release": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq" }; break;
case "query-state": required=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq" }; allowed=new[] { "protocol", "contract", "renderMode", "providerId", "revision", "instance", "session", "op", "seq" }; break;
default: throw new ContractException("invalid-message", "Unknown request");
}
Check.That(required.All(k => m[k] != null && m[k].Type != JTokenType.Null) && m.Properties().All(p => allowed.Contains(p.Name)), "Missing/unexpected request field");
foreach (var p in m.Properties()) if (p.Name != "seq" && p.Name != "displayEpoch" && p.Name != "warmLimitBytes" && p.Name != "setDefault" && p.Name != "targets" && p.Name != "choiceIds" && p.Name != "layout" && p.Name != "resource" && p.Name != "grant") Check.That(p.Value.Type == JTokenType.String && Check.Id((string)p.Value), "Invalid ID/string");
foreach (var name in new[] { "seq", "displayEpoch", "warmLimitBytes" }) if (m[name] != null) Check.That(m[name].Type == JTokenType.Integer && (long)m[name] >= (name == "warmLimitBytes" ? 0 : 1) && (long)m[name] <= 9007199254740991L, "Invalid integer");
foreach (var name in new[] { "targets", "choiceIds" }) if (m[name] != null) { var a = m[name] as JArray; Check.That(a != null && a.Count > 0 && a.Count <= 32 && a.All(t => t.Type == JTokenType.String && Check.Id((string)t)) && a.Select(t => (string)t).Distinct(StringComparer.Ordinal).Count() == a.Count, "Invalid ID array"); }
if (m["setDefault"] != null) Check.That(m["setDefault"].Type == JTokenType.Boolean, "Invalid default flag");
if ((string)m["op"] == "select") { var mode=(string)m["mode"]; Check.That(new[] { "follow", "original", "selected" }.Contains(mode) && (mode == "selected" ? m["resource"] is JObject : m["resource"] == null), "Invalid selection"); if (m["layout"] != null) Layout.Read(m["layout"]); if (m["resource"] != null) Check.Parse<ResourceRef>(m["resource"].ToString()).Validate(); }
if (m["grant"] != null) { var g=Check.Parse<Grant>(m["grant"].ToString()); Check.That(g.residentDeltaBytes >= 0 && g.peakAdditionalBytes >= 0 && g.residentDeltaBytes <= 9007199254740991L && g.peakAdditionalBytes <= 9007199254740991L, "Invalid grant"); }
} } }
